// grammar rule: [title, rule, examples]
export const GRAMMAR = [
  ['Subject–verb agreement', 'A singular subject takes a singular verb; a plural subject takes a plural verb.', 'She writes daily.|They write daily.'],
  ['Each / every', '"Each" and "every" take a singular verb.', 'Each of the boys has a pen.|Every student is present.'],
  ['Either…or / neither…nor', 'The verb agrees with the subject nearer to it.', 'Neither the teacher nor the students were late.|Either the students or the teacher is to blame.'],
  ['One of the + plural noun', '"One of the" is followed by a plural noun and a singular verb.', 'One of my friends is a doctor.'],
  ['Collective nouns', 'A collective noun takes a singular verb when the group acts as one unit.', 'The committee has made its decision.'],
  ['Since / for', '"Since" is used with a point of time; "for" with a period of time.', 'I have lived here since 2015.|I have lived here for ten years.'],
  ['Present perfect with past time', 'The present perfect is not used with a definite past time; use the simple past.', 'I saw him yesterday. (not "have seen him yesterday")'],
  ['Articles: a / an', '"An" is used before a vowel sound, "a" before a consonant sound.', 'an hour, an honest man|a university, a one-rupee coin'],
  ['The before superlatives', '"The" is used before a superlative adjective.', 'She is the tallest girl in the class.'],
  ['Comparatives with than', 'A comparative adjective is followed by "than".', 'He is taller than his brother.'],
  ['Double comparatives', 'Do not use "more" with a comparative form.', 'She is smarter than me. (not "more smarter")'],
  ['Superior / inferior', '"Superior", "inferior", "senior" and "junior" are followed by "to", not "than".', 'He is senior to me.'],
  ['Prefer … to', '"Prefer" is followed by "to", not "than".', 'I prefer tea to coffee.'],
  ['Unless', '"Unless" already means "if not"; do not add "not".', 'Unless you work hard, you will fail.'],
  ['Lest … should', '"Lest" is followed by "should".', 'Walk carefully lest you should fall.'],
  ['Hardly … when', '"Hardly" and "scarcely" are followed by "when", "no sooner" by "than".', 'Hardly had he arrived when it rained.|No sooner had he left than it rained.'],
  ['Active and passive voice', 'In the passive, the object becomes the subject and the verb is "be" + past participle.', 'Active: Ram wrote a letter.|Passive: A letter was written by Ram.'],
  ['Direct and indirect speech', 'In reported speech after a past reporting verb, the tense usually moves one step back.', 'He said, "I am tired." → He said that he was tired.'],
  ['Question tags', 'A positive statement takes a negative tag and a negative statement a positive tag.', 'She is coming, isn\'t she?|You don\'t smoke, do you?'],
  ['Conditionals (type 2)', 'For unreal present conditions use "if + past simple, would + verb".', 'If I were rich, I would travel.'],
  ['Conditionals (type 3)', 'For unreal past conditions use "if + past perfect, would have + past participle".', 'If he had studied, he would have passed.'],
  ['Few / a few / the few', '"Few" means hardly any; "a few" means some; "the few" means the small number that exist.', 'Few people came.|A few people came.'],
  ['Less / fewer', '"Fewer" is used with countable nouns, "less" with uncountable nouns.', 'fewer books|less water'],
  ['Between / among', '"Between" is used for two, "among" for more than two.', 'Divide it between the two brothers.|Divide it among the five friends.'],
  ['Beside / besides', '"Beside" means next to; "besides" means in addition to.', 'Sit beside me.|Besides English, he knows Hindi.'],
  ['Its / it\'s', '"Its" shows possession; "it\'s" means "it is".', 'The dog wagged its tail.|It\'s raining.'],
  ['Who / whom', '"Who" is a subject; "whom" is an object.', 'Who called you?|Whom did you call?'],
  ['Gerund after prepositions', 'A verb after a preposition takes the -ing form.', 'He is fond of reading.|She is good at singing.'],
  ['Infinitive without "to"', 'After "let", "make" and modal verbs, the infinitive is used without "to".', 'Let him go.|You must leave now.'],
  ['Uncountable nouns', 'Words like information, advice, furniture and luggage have no plural form.', 'She gave me some useful advice.'],
]

